#include <iostream>
#include <vector>
using namespace std;

long long compute(long long num, int length) {
    static vector<long long> p(17);
    if (p[1] == 0) {
        for (int i = 1; i < 17; ++i) {
            p[i] = p[i - 1] * 10 + 1;
        }
    }
    if (length == 0) return 0;
    long long quotient = num / p[length];
    long long remainder = num % p[length];
    long long option1 = quotient * length;
    long long option2 = 0;
    if (remainder != 0) {
        long long res1 = compute(remainder, length - 1);
        long long res2 = length + compute(p[length] - remainder, length - 1);
        option2 = min(res1, res2);
    }
    return option1 + option2;
}

int main() {
    ios::sync_with_stdio(false);
    long long n;
    cin >> n;
    cout << compute(n, 16) << "\n";
    return 0;
}
